(()=>{
const $=s=>document.querySelector(s),form=$('#admin-form');let generation=0;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
function error(message=''){$('#admin-error').textContent=message;$('#admin-error').hidden=!message;}
async function api(path,options){const r=await fetch('/api/calendar'+path,{cache:'no-store',...options});let data;try{data=await r.json()}catch{throw new Error('Calendar unavailable. Please try again.')}if(!r.ok)throw new Error(data.error);return data;}
async function load(){const version=++generation;error();try{const month=$('#admin-month').value,data=await api('/admin?month='+month);if(version!==generation)return;const first=new Date(month+'-01T12:00:00Z'),count=new Date(Date.UTC(first.getUTCFullYear(),first.getUTCMonth()+1,0)).getUTCDate();let html='<span></span>'.repeat((first.getUTCDay()+6)%7);
for(let i=1;i<=count;i++){const date=month+'-'+String(i).padStart(2,'0');html+=`<div class="owner-day"><b>${i}</b>${[1,2].map(scanner=>{const row=data.reservations.find(r=>r.scanner===scanner&&r.start<=date&&r.end>=date);return `<span class="scanner-state ${row?.status||''}" title="${esc(row?.reference||'')}">${scanner}: ${row?({booked:'Booked',hold:'Held',blocked:'Blocked'}[row.status]):'Free'}</span>`}).join('')}</div>`;}$('#owner-calendar').innerHTML=html;
$('#reservation-list').innerHTML='<h3>Reservations this month</h3>'+(data.reservations.length?data.reservations.map(r=>`<article class="reservation-row"><div><h4>${esc(r.reference||'Temporary online hold')}</h4><p>Scanner ${r.scanner} · ${r.status==='booked'?'Manual booking':r.status==='blocked'?'Unavailable':'15-minute hold'} ${r.days?'· '+r.days+' days · £'+r.price:''}</p><p>${r.method==='service'?'Unavailable':'Stock reserved'}: ${fmt(r.start)} – ${fmt(r.end)} inclusive</p>${r.method!=='service'?`<p>${r.method==='delivery'?'Delivery':'Collect'}: ${fmt(r.rentalStart)} · ${r.method==='delivery'?'Post back':'Return locally'}: ${fmt(r.returnDate)}</p>`:''}</div><button class="cancel-button" data-cancel="${r.id}">Cancel reservation</button></article>`).join(''):'<p class="admin-empty">No reservations this month. Both scanners are free.</p>');
document.querySelectorAll('[data-cancel]').forEach(button=>button.onclick=()=>{const id=button.dataset.cancel,wrapper=document.createElement('div');wrapper.className='cancel-confirm';wrapper.innerHTML='<span>Release these dates?</span><button class="cancel-button" data-yes>Yes, cancel</button><button class="text-button" data-no>Keep</button>';button.replaceWith(wrapper);wrapper.querySelector('[data-no]').onclick=load;wrapper.querySelector('[data-yes]').onclick=async()=>{try{await api('/admin',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({id})});$('#admin-message').textContent='Reservation cancelled. These dates are available again.';await load();}catch(e){error(e.message);}};});
}catch(e){error(e.message);}}
form.elements.kind.onchange=()=>{const blocked=form.elements.kind.value==='blocked';$('#rental-admin-fields').hidden=blocked;$('#block-end-label').hidden=!blocked;form.elements.end.required=blocked;form.elements.scanner.querySelector('[value="0"]').disabled=blocked;if(blocked&&form.elements.scanner.value==='0')form.elements.scanner.value='1';$('#admin-form-hint').textContent=blocked?'Block the entire unavailable period, including any cleaning time. Both end dates are included.':'Rental bookings automatically include postage and cleaning time. No payment is taken.';};
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type="submit"]');button.disabled=true;error();$('#admin-message').textContent='';try{const body=Object.fromEntries(new FormData(form));body.id=crypto.randomUUID();const data=await api('/admin',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});$('#admin-message').textContent=`Saved for scanner ${data.reservation.scanner}. Stock reserved ${fmt(data.reservation.start)} – ${fmt(data.reservation.end)}.`;$('#admin-month').value=data.reservation.rentalStart.slice(0,7);form.elements.reference.value='';await load();}catch(e){error(e.message)}finally{button.disabled=false;}};
$('#admin-month').onchange=load;$('#admin-refresh').onclick=load;
api('/context').then(context=>{if(!context.admin){error('This calendar is only available to the site owner.');return;}$('#admin-content').hidden=false;$('#admin-month').value=context.today.slice(0,7);form.elements.start.min=context.today;form.elements.end.min=context.today;load();}).catch(e=>error(e.message));
setInterval(()=>{if(!$('#admin-content').hidden&&!document.querySelector('.cancel-confirm'))load();},30000);
})();
